            return type(arg)(*vals) if hasattr(arg, "_fields") else tuple(vals)

        tys = make_tuple([x[0] for x in spec])
        keys = make_tuple([x[1] for x in spec])
        return (tys, keys)
    else:
        raise TypeError("Unsupported type: %s" % type(arg))

